rawJsonSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "document_type": {
      "description": "The type of document that has been downloaded.",
      "type": "string",
      "enum": [
        "Certificate of Name Change",
        "Certificate of Incorporation",
        "Confirmation Statement / Annual Report"
      ]
    },
    "filing_date": {
      "description": "The date on which the document was officially filed, as reported by the original source. This date must be converted and stored strictly in MM/DD/YYYY format.",
      "type": "string"
    },
    "storage_path": {
      "description": "The complete S3 link leading to the document saved in the datastore.",
      "type": "string"
    },
    "file_name": {
      "description": "The exact name of the file as it is stored in the datastore, including the file extension.",
      "type": "string"
    },
    "download_status": {
      "description": "Whether the document file was successfully downloaded and saved to the datastore.",
      "type": "boolean"
    }
  },
  "required": [
    "document_type",
    "filing_date",
    "storage_path",
    "file_name",
    "download_status"
  ]
}
